function calcData(){
 const serviceItems=[];
 const externalItems=[];
 function add(arr,name,amount){if(Number(amount)>0)arr.push([name,Number(amount)])}
 add(serviceItems,"필수 · 전담 장례지도사",requiredPersonnel.director);
 add(serviceItems,"필수 · 입관용품 일체",requiredPersonnel.embalmingSupplies);
 add(serviceItems,"필수 · 보조 장례지도사(입관식)",requiredPersonnel.assistantDirector);
 add(serviceItems,"수의 · "+(state.shroud||"미선택"),state.shroudPrice);
 add(serviceItems,"관 · "+(state.coffin||"미선택"),state.coffinPrice);
 add(serviceItems,"매장용 횡대·부대품",val("crossBarCost"));
 add(serviceItems,"유골함 · "+(state.urn||"미선택"),state.urnPrice);
 add(serviceItems,"남자 상복 "+val("maleSuit")+"벌",val("maleSuit")*unit.maleSuit);
 add(serviceItems,"여자 상복 "+val("femaleSuit")+"벌",val("femaleSuit")*unit.femaleSuit);
 add(serviceItems,"접객 도우미 "+val("helper")+"인",val("helper")*unit.helper);
 if(document.getElementById("limo").checked)add(serviceItems,"리무진",unit.limo);
 if(document.getElementById("bus").checked)add(serviceItems,"장례버스",unit.bus);
 add(serviceItems,"추가 차량·거리비",val("vehicleExtra"));
 add(externalItems,"장례식장·안치·시설비",val("hallCost")+val("hallEtc"));
 add(externalItems,"음식·접객비",val("foodCost"));
 add(externalItems,"화장시설 이용료",val("cremationCost"));
 add(externalItems,"장지·봉안시설비",val("burialCost"));
 const service=serviceItems.reduce((s,x)=>s+x[1],0);
 const external=externalItems.reduce((s,x)=>s+x[1],0);
 return {serviceItems,externalItems,service,external,total:service+external};
}
